def max_product(num_str: str, N: int, K: int) -> int:
    # dp[i][k] = maximum product for first i digits with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    # base case: no multiplication signs
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])
    # fill DP
    for k in range(1, K + 1):
        # need at least k+1 digits to place k cuts
        for i in range(k + 1, N + 1):
            best = 0
            # last part starts at j
            for j in range(k, i):
                part = int(num_str[j:i])
                prod = dp[j][k - 1] * part
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[N][K]

