def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        # Determine variable part
        if degree == 0:
            var = ''
        elif degree == 1:
            var = 'x'
        else:
            var = f'x^{degree}'
        # Determine coefficient string
        if abs_coeff == 1 and var:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        terms.append(f"{sign}{coeff_str}{var}")
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    enc_to_orig = {}
    orig_to_enc = {}
    for e, o in zip(encoded, original):
        if e in enc_to_orig:
            if enc_to_orig[e] != o:
                return "Failed"
        else:
            enc_to_orig[e] = o
        if o in orig_to_enc:
            if orig_to_enc[o] != e:
                return "Failed"
        else:
            orig_to_enc[o] = e
    if len(enc_to_orig) != 26:
        return "Failed"
    decoded = []
    for ch in message:
        if ch not in enc_to_orig:
            return "Failed"
        decoded.append(enc_to_orig[ch])
    return "".join(decoded)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    total = 1  # count the sequence that ends here
    for k in range(1, last // 2 + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

def count_coprime_pairs(x0: int, y0: int) -> int:
    # Helper function to compute gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    n = y0 // x0
    count = 0
    a = 1
    while a * a <= n:
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        a += 1
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    max_steps = 10
    queue = deque([(A, 0)])
    visited = {A}
    while queue:
        current, steps = queue.popleft()
        if steps > max_steps:
            continue
        if current == B:
            return steps
        if steps == max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque
    # Build a mapping from each digit to the list of digits it can transform into
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))

    start_str = str(n)
    visited = {int(start_str)}
    queue = deque([start_str])

    while queue:
        cur = queue.popleft()
        for i, ch in enumerate(cur):
            if ch in rule_map:
                for rep in rule_map[ch]:
                    new_str = cur[:i] + rep + cur[i+1:]
                    new_int = int(new_str)
                    if new_int not in visited:
                        visited.add(new_int)
                        queue.append(new_str)

    return len(visited)

def calculate_score(system: int, points: str) -> list:
    scores = []
    player = 0
    opponent = 0
    for p in points:
        if p == 'W':
            player += 1
        elif p == 'L':
            opponent += 1
        # Check if game finished
        if (player >= system or opponent >= system) and abs(player - opponent) >= 2:
            scores.append(f"{player}:{opponent}")
            player = 0
            opponent = 0
    # If there is an unfinished game, add its current score
    if player != 0 or opponent != 0:
        scores.append(f"{player}:{opponent}")
    return scores

