def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if not areas:
        return l
    # Clamp intervals to the road bounds and discard empty ones
    intervals = [(max(0, a), min(l, b)) for a, b in areas if max(0, a) < min(l, b)]
    if not intervals:
        return l
    intervals.sort(key=lambda x: x[0])
    total_cleared = 0
    cur_start, cur_end = intervals[0]
    for s, e in intervals[1:]:
        if s <= cur_end:  # overlap or touch
            if e > cur_end:
                cur_end = e
        else:
            total_cleared += cur_end - cur_start
            cur_start, cur_end = s, e
    total_cleared += cur_end - cur_start
    remaining = l - total_cleared
    return remaining if remaining > 0 else 0

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Ensure we only consider the first n items
    items = volumes[:n]
    # DP array where dp[c] is the maximum volume that can be achieved with capacity c
    dp = [0] * (V + 1)
    for vol in items:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            new_val = dp[cap - vol] + vol
            if new_val > dp[cap]:
                dp[cap] = new_val
    max_occupied = dp[V]
    return V - max_occupied

def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of a modulo b using the Extended Euclidean Algorithm.
    Returns None if the inverse does not exist (i.e., a and b are not coprime).
    """
    def egcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = egcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x, _ = egcd(a, b)
    if g != 1:
        return None
    return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappy = 0
    best_day = 0
    for i, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            unhappy = total - 8
            if unhappy > max_unhappy:
                max_unhappy = unhappy
                best_day = i
    return best_day if max_unhappy > 0 else 0

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0
    inc = [1] * n
    dec = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    max_len = 0
    for i in range(n):
        cur = inc[i] + dec[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
